// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type PriceGapProps = Record<string, any>;

const PriceGap: React.FC<PriceGapProps> = ({
  backgroundColor = "#f8fafc",
  transparentBackground = false,
  durationInSeconds = 5,
  leftPrice = "2.495",
  rightPrice = "2.510",
  initialGap = 15,
  finalGap = 100,
  badgePrefix = "$",
  badgeSuffix = "K",
  tagBgColor = "#ffffff",
  tagTextColor = "#0f172a",
  indicatorColor = "#cbd5e1",
  badgeBgColor = "#3b82f6",
  badgeTextColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const s = Math.min(width, height);

  // Animation timings (frames)
  const leftEntryStart = 5;
  const rightEntryStart = 15;
  const indicatorStart = 30;
  const badgeStart = 45;
  const growthStart = 70;

  // Dynamically calculate growth duration based on total available time
  const totalFrames = durationInSeconds * fps;
  const holdFramesAtEnd = 30; // Hold for 1 second at the end
  const growthDuration = Math.max(15, totalFrames - growthStart - holdFramesAtEnd);

  // Springs & Interpolations
  const leftEntry = spring({
    frame: frame - leftEntryStart,
    fps,
    config: { damping: 14, mass: 1 },
  });
  
  const rightEntry = spring({
    frame: frame - rightEntryStart,
    fps,
    config: { damping: 14, mass: 1 },
  });
  
  const indicatorScale = spring({
    frame: frame - indicatorStart,
    fps,
    config: { damping: 14, mass: 1 },
  });
  
  const badgeScale = spring({
    frame: frame - badgeStart,
    fps,
    config: { damping: 12, mass: 0.8 },
  });

  const growthProgress = interpolate(
    frame,
    [growthStart, growthStart + growthDuration],
    [0, 1],
    {
      easing: Easing.inOut(Easing.cubic),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Value calculation
  const currentGapValue = Math.round(
    interpolate(growthProgress, [0, 1], [initialGap, finalGap])
  );

  // Layout geometry calculations
  const centerX = width / 2;
  const centerY = height * 0.45; // Slightly above center to account for 9:16 safe zones

  const baseDistance = width * 0.22; // Initial half-distance between tags
  const maxExtraDistance = width * 0.15; // Total extra distance to expand
  const extraDistance = growthProgress * maxExtraDistance;
  const currentDistance = baseDistance + extraDistance;

  // Positional calculations mapping edge entries to final layout spots
  const leftTagXOffset = interpolate(leftEntry, [0, 1], [-width, 0]);
  const leftTagFinalX = centerX - currentDistance + leftTagXOffset;

  const rightTagXOffset = interpolate(rightEntry, [0, 1], [width, 0]);
  const rightTagFinalX = centerX + currentDistance + rightTagXOffset;

  const indicatorY = centerY + s * 0.15;
  const indicatorWidth = (currentDistance * 2) * indicatorScale;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        transition: "none",
        overflow: "hidden",
      }}
    >
      {/* Indicator Line */}
      <div
        style={{
          position: "absolute",
          left: centerX,
          top: indicatorY,
          width: indicatorWidth,
          height: 4,
          backgroundColor: indicatorColor,
          transform: "translate(-50%, -50%)",
          opacity: indicatorScale > 0.01 ? 1 : 0,
          transition: "none",
        }}
      >
        {/* Left Measurement Tick */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: "50%",
            transform: "translateY(-50%)",
            width: 4,
            height: s * 0.05,
            backgroundColor: indicatorColor,
            borderRadius: 2,
            transition: "none",
          }}
        />
        {/* Right Measurement Tick */}
        <div
          style={{
            position: "absolute",
            right: 0,
            top: "50%",
            transform: "translateY(-50%)",
            width: 4,
            height: s * 0.05,
            backgroundColor: indicatorColor,
            borderRadius: 2,
            transition: "none",
          }}
        />
      </div>

      {/* Pop-in Badge */}
      <div
        style={{
          position: "absolute",
          left: centerX,
          top: indicatorY,
          transform: `translate(-50%, -50%) scale(${badgeScale})`,
          backgroundColor: badgeBgColor,
          color: badgeTextColor,
          padding: `${s * 0.015}px ${s * 0.04}px`,
          borderRadius: 999, // Pill shape
          fontSize: s * 0.045,
          fontWeight: 800,
          fontVariantNumeric: "tabular-nums", // Prevents width jitter during rollup
          boxShadow: "0 10px 25px -5px rgba(0, 0, 0, 0.2)",
          opacity: badgeScale > 0.01 ? 1 : 0,
          transition: "none",
          zIndex: 10,
        }}
      >
        {badgePrefix}
        {currentGapValue}
        {badgeSuffix}
      </div>

      {/* Left Price Tag */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          transform: `translate(${leftTagFinalX}px, ${centerY}px) translate(-50%, -50%)`,
          backgroundColor: tagBgColor,
          color: tagTextColor,
          padding: `${s * 0.03}px ${s * 0.06}px`,
          borderRadius: 999, // Pill shape
          fontSize: s * 0.06,
          fontWeight: 800,
          boxShadow:
            "0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04)",
          opacity: leftEntry > 0.01 ? 1 : 0,
          transition: "none",
        }}
      >
        {leftPrice}
      </div>

      {/* Right Price Tag */}
      <div
        style={{
          position: "absolute",
          left: 0,
          top: 0,
          transform: `translate(${rightTagFinalX}px, ${centerY}px) translate(-50%, -50%)`,
          backgroundColor: tagBgColor,
          color: tagTextColor,
          padding: `${s * 0.03}px ${s * 0.06}px`,
          borderRadius: 999, // Pill shape
          fontSize: s * 0.06,
          fontWeight: 800,
          boxShadow:
            "0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04)",
          opacity: rightEntry > 0.01 ? 1 : 0,
          transition: "none",
        }}
      >
        {rightPrice}
      </div>
    </AbsoluteFill>
  );
};

export default PriceGap;